'use strict';
// Vendored copy kept with the project so builds work offline.
const crypto = require('crypto');
const OAuth = require('oauth-1.0a');
const got = require('got');

class NsApiWrapper {
  constructor(options) {
    this.consumer_key = options.consumer_key;
    this.consumer_secret_key = options.consumer_secret_key;
    this.token = options.token;
    this.token_secret = options.token_secret;
    this.version = '1.0';
    this.algorithm = 'HMAC-SHA256';
    this.realm = options.realm;
    this.base_url = options.base_url;
  }

  getAuthorizationHeader(options) {
    const oauth = OAuth({
      consumer: { key: this.consumer_key, secret: this.consumer_secret_key },
      realm: this.realm,
      signature_method: this.algorithm,
      hash_function(base_string, key) {
        return crypto.createHmac('sha256', key).update(base_string).digest('base64');
      },
    });
    return oauth.toHeader(
      oauth.authorize(
        { url: options.url, method: options.method },
        { key: this.token, secret: this.token_secret },
      ),
    );
  }

  request(opts) {
    const { path = '*', method = 'GET', body = '', heads = {} } = opts;
    let baseUrl = this.base_url;
    if (!baseUrl) {
      const host = this.realm.toLowerCase().replace(/_/g, '-');
      baseUrl = `https://${host}.suitetalk.api.netsuite.com/services/rest`;
    }
    const uri = `${baseUrl}/${path}`;
    const options = { url: uri, method, headers: { prefer: 'transient' }, throwHttpErrors: true, decompress: true };
    if (['POST', 'PUT', 'PATCH'].includes(method.toUpperCase())) options.body = body;
    options.headers = { ...options.headers, ...this.getAuthorizationHeader(options), ...heads };
    return got(options).then((res) => ({ ...res, data: res.body ? JSON.parse(res.body) : null }));
  }
}

module.exports = NsApiWrapper;
